import React from 'react';
import { motion } from 'framer-motion';

/**
 * Estado vacío reutilizable dentro de Caja (sin pedidos, sin facturas, sin
 * selección). El ícono flota suavemente en loop para que la pantalla no se
 * sienta "muerta" cuando no hay datos.
 */
const CashierEmptyState = ({ icon: Icon, title, message }) => (
  <div className="cashier-empty">
    <motion.div
      className="cashier-empty-icon"
      animate={{ y: [0, -8, 0] }}
      transition={{ duration: 2.4, repeat: Infinity, ease: 'easeInOut' }}
    >
      <Icon size={30} strokeWidth={1.75} />
    </motion.div>
    <p className="cashier-empty-title">{title}</p>
    {message && <p className="cashier-empty-message">{message}</p>}
  </div>
);

export default CashierEmptyState;
